import os
import re
import unicodedata
from pathlib import PurePosixPath
from typing import Optional, Dict, Set
import hashlib
import hmac
import time
import secrets

# Configuration
BASE_DOCUMENT_ROOT = "/var/www/documents"
SESSION_SECRET = secrets.token_bytes(32)
MAX_PATH_LENGTH = 4096
# Maximum lifetime of a session token in seconds (e.g. 1 hour)
SESSION_MAX_AGE = 3600

# Access control lists: role -> set of allowed path prefixes
ACL_RULES: Dict[str, Set[str]] = {
    "public": {"/public/", "/shared/readme"},
    "employee": {"/public/", "/shared/", "/internal/reports/"},
    "admin": {"/public/", "/shared/", "/internal/", "/secrets/"},
}

class Session:
    def __init__(self, user_id: str, role: str):
        self.user_id = user_id
        self.role = role
        self.created_at = time.time()
        self.token = self._generate_token()

    def _generate_token(self) -> str:
        payload = f"{self.user_id}:{self.role}:{self.created_at}"
        sig = hmac.new(SESSION_SECRET, payload.encode(), hashlib.sha256).hexdigest()
        return f"{payload}:{sig}"

    @staticmethod
    def verify_token(token: str) -> Optional['Session']:
        parts = token.rsplit(':', 1)
        if len(parts) != 2:
            return None
        payload, sig = parts
        expected = hmac.new(SESSION_SECRET, payload.encode(), hashlib.sha256).hexdigest()
        if not hmac.compare_digest(sig, expected):
            return None
        fields = payload.split(':')
        if len(fields) != 3:
            return None
        # Safely parse the creation timestamp
        try:
            created_at = float(fields[2])
        except (ValueError, TypeError):
            return None
        # Enforce session expiration to prevent indefinitely-valid tokens
        now = time.time()
        if created_at > now:
            # created_at in the future is invalid
            return None
        if now - created_at > SESSION_MAX_AGE:
            return None
        session = Session.__new__(Session)
        session.user_id = fields[0]
        session.role = fields[1]
        session.created_at = created_at
        session.token = token
        return session


def sanitize_path_component(component: str) -> str:
    """Remove null bytes and control characters from a path component."""
    return ''.join(c for c in component if ord(c) >= 0x20 and c != '\x7f')


def check_path_traversal(path: str) -> bool:
    """Check for obvious path traversal patterns. Returns True if safe."""
    # Check for null bytes
    if '\x00' in path:
        return False
    # Check for standard traversal patterns
    if re.search(r'(^|/)\.\.(/|$)', path):
        return False
    # Check for backslash-based traversal
    if '\\' in path:
        return False
    return True


def normalize_unicode_path(path: str) -> str:
    """Normalize Unicode characters in path to their canonical form.
    This handles cases where visually similar characters map to ASCII.
    Uses NFKC normalization which decomposes then recomposes by compatibility."""
    normalized = unicodedata.normalize('NFKC', path)
    return normalized


def check_acl(role: str, requested_path: str) -> bool:
    """Verify that the role has access to the requested path prefix."""
    allowed_prefixes = ACL_RULES.get(role, set())
    for prefix in allowed_prefixes:
        if requested_path.startswith(prefix):
            return True
    return False


def resolve_document_path(requested_path: str) -> Optional[str]:
    """Resolve the requested path to an absolute filesystem path.
    Ensures the result is within BASE_DOCUMENT_ROOT."""
    # Combine with document root
    full_path = os.path.normpath(os.path.join(BASE_DOCUMENT_ROOT, requested_path.lstrip('/')))
    # Verify it's still within the document root
    if not full_path.startswith(BASE_DOCUMENT_ROOT):
        return None
    return full_path


def serve_document(session_token: str, requested_path: str) -> Dict:
    """Main entry point: serve a document based on session and path.

    Security pipeline:
    1. Validate session
    2. Length check
    3. Sanitize control characters
    4. Normalize Unicode
    5. Check path traversal patterns
    6. Verify ACL permissions
    7. Resolve filesystem path
    8. Read and return document
    """
    # Step 1: Validate session
    session = Session.verify_token(session_token)
    if session is None:
        return {"error": "Invalid session", "status": 401}

    # Step 2: Length check
    if len(requested_path) > MAX_PATH_LENGTH:
        return {"error": "Path too long", "status": 400}

    # Step 3: Sanitize control characters
    clean_path = sanitize_path_component(requested_path)

    # Step 4: Normalize Unicode BEFORE security checks
    normalized_path = normalize_unicode_path(clean_path)

    # Step 5: Check for path traversal on normalized path
    if not check_path_traversal(normalized_path):
        return {"error": "Invalid path", "status": 400}

    # Step 6: Verify ACL on normalized path
    if not check_acl(session.role, normalized_path):
        return {"error": "Access denied", "status": 403}

    # Step 7: Resolve to filesystem path using same normalized version
    fs_path = resolve_document_path(normalized_path)
    if fs_path is None:
        return {"error": "Path resolution failed", "status": 400}

    # Step 8: Read document
    try:
        if not os.path.isfile(fs_path):
            return {"error": "Not found", "status": 404}
        with open(fs_path, 'r') as f:
            content = f.read()
        return {"content": content, "status": 200, "path": normalized_path}
    except (IOError, OSError):
        return {"error": "Read error", "status": 500}
